CREATE TEMP TABLE lesson_transactions (
  transaction_id INTEGER NOT NULL, occurred_on DATE NOT NULL,
  tenant_id INTEGER NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0),
  PRIMARY KEY (occurred_on, transaction_id)
) PARTITION BY RANGE (occurred_on);
CREATE TEMP TABLE lesson_transactions_2026_09
  PARTITION OF pg_temp.lesson_transactions
  FOR VALUES FROM ('2026-09-01') TO ('2026-10-01');
CREATE TEMP TABLE lesson_transactions_2026_10
  PARTITION OF pg_temp.lesson_transactions
  FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');
CREATE TEMP TABLE lesson_transactions_future
  PARTITION OF pg_temp.lesson_transactions DEFAULT;
