CREATE TEMP TABLE lesson_shard_directory (
  tenant_id INTEGER PRIMARY KEY, shard_id TEXT NOT NULL,
  route_epoch INTEGER NOT NULL, ownership_ready BOOLEAN,
  planned_rps INTEGER NOT NULL CHECK (planned_rps >= 0)
);
CREATE TEMP TABLE lesson_shard_requests (
  request_id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL,
  client_epoch INTEGER NOT NULL
);
