CREATE TEMP TABLE lesson_tenant_invoices (
  tenant_id INTEGER NOT NULL, invoice_id INTEGER NOT NULL,
  amount INTEGER NOT NULL CHECK (amount > 0),
  PRIMARY KEY (tenant_id, invoice_id)
);
CREATE TEMP TABLE lesson_tenant_payments (
  tenant_id INTEGER NOT NULL, payment_id INTEGER NOT NULL,
  invoice_id INTEGER NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0),
  PRIMARY KEY (tenant_id, payment_id),
  FOREIGN KEY (tenant_id, invoice_id)
    REFERENCES pg_temp.lesson_tenant_invoices (tenant_id, invoice_id)
);
